self.KB_CONTENT["card:793412"]={"id":"card:793412","ty":"card","sourceId":"793412","title":"『保養項目建立作業』中的『保養週期 (MA003)』為何？","ver":"GP4以上","topic":"其他","keywords":[],"y":"other","answer":"* 請選擇此項保養項目的保養週期為「1.月」、「2.日」或「3.時」。* 預設為「1.月」。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
