self.KB_CONTENT["card:791911"]={"id":"card:791911","ty":"card","sourceId":"791911","title":"『請修工單憑證列印』中的『選擇請修日期 (TA003)』為何？","ver":"GP4以上","topic":"憑證","keywords":["憑證","工單"],"y":"other","answer":"* 可按(icon)或[F2]日期快手，選擇欲列印「請修日期」在哪一段區間的請修資料。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
